def _finalize_instruction(self) -> str:
        if not self.finalize_tools:
            return FINALIZE_INSTRUCTION
        names = ", ".join(sorted(self.finalize_tools))
        return (
            "The investigation budget for this run is used up. Do not investigate further. "
