            "you could not establish as unresolved with a limitation instead of guessing."
        )

def _project_lcsp_runtime_context(request: ModelRequest) -> ModelRequest:
    """Append immutable pipeline identifiers without copying governed evidence into prompts."""
    context = request.runtime.context
    if context is not None and not isinstance(context, LCSPRunContext):
        if isinstance(context, dict):
            context = LCSPRunContext(**context)
        else:
            context = None

    lines = bounded_context_lines(context)
    if not lines:
        return request

    # Idempotency is shared by initial investigations, exact resumes and legal
    # preparation. It is not a routing discriminator. Boundaries/root dispatch own
    # the task instruction; this shared middleware only appends immutable metadata.
    context_block = (
        "LCSP runtime context (immutable identifiers; not evidence):\n"
        + "\n".join(f"- {line}" for line in lines)
        + "\nUse these identifiers when delegating and calling governed tools. "
        "Do not alter them or treat them as proof of compliance."
    )
    new_content: list[Any] = list(request.system_message.content_blocks)
    new_content.append({"type": "text", "text": context_block})
    return request.override(system_message=SystemMessage(content=new_content))

def get_language_prompt_instruction(locale: str) -> str:
    """Generate dynamic system prompt instruction for the main agent."""
    from runtime_instruction_bundle import runtime_instruction
    return runtime_instruction("runtime.response-language")
    normalized_locale = str(locale).strip().lower() if locale else DEFAULT_RESPONSE_LANGUAGE
    definition = SUPPORTED_LOCALES.get(normalized_locale) or SUPPORTED_LOCALES.get(DEFAULT_RESPONSE_LANGUAGE, SUPPORTED_LOCALES["en"])
    return (
        f"Final Response Language Directive:\n"
        f"- {definition.instruction}\n"
        f"- Keep all technical identifiers, file paths, URLs, citations/references, code blocks/inline code, "
        f"API field names, Jira/GitHub identifiers, and enum/constant values in their canonical format.\n"
        f"- Do NOT translate internal machine identifiers, tool names, or structured JSON keys."
    )

